export const FITOUT_CAST_IDS=Object.freeze(Object.keys(FITOUT_CAST_STORIES));
export function characterLines(id){const story=FITOUT_CAST_STORIES[id];return story?Object.values(story.lines).flat():[]}
export function castLine(id,{context='idle',index=0,otherId=null}={}){const story=FITOUT_CAST_STORIES[id];if(!story)return'';if(otherId&&story.relationships[otherId])return story.relationships[otherId];const pool=story.lines[context]||characterLines(id);return pool[Math.abs(Number(index)||0)%pool.length]||''}
export function applyCastStory(profile,id){const story=FITOUT_CAST_STORIES[id];if(!story)return profile;profile.storyId=id;profile.biography={...profile.biography,summary:story.biography,reputation:story.goal};profile.traits=[...story.traits];profile.relationships={...story.relationships};profile.goal=story.goal;profile.fear=story.fear;return profile}

const stateContext=state=>({to_supply:'moving',to_work:'moving',walk:'moving',carrying:'carrying',working:'working'}[state]||'idle');
export class ContextualDialogueDirector{
  constructor(){this.counts=new Map();this.lastByActor=new Map()}
  resolve(world={}){if(world.otherId&&world.relationshipMoment)return{context:'relationship',reason:`рядом ${world.otherId}`};if(world.event==='mistake'||world.mistake)return{context:'mistake',reason:'обнаружена ошибка'};if(world.event==='success'||world.completed)return{context:'success',reason:'работа завершена'};if(world.blocked)return{context:'blocked',reason:'маршрут или работа заблокированы'};if((world.pressure||0)>=70)return{context:'pressure',reason:'высокое давление срока'};if(world.event==='arrival')return{context:'arrival',reason:'начало забега'};const context=stateContext(world.state);return{context,reason:`состояние ${world.state||'idle'}${world.order?.kind?` · ${world.order.kind}`:''}`}}
  next(id,world={}){const story=FITOUT_CAST_STORIES[id];if(!story)return{text:'',context:'idle',reason:'неизвестный персонаж',index:0};const resolved=this.resolve(world);if(resolved.context==='relationship'){const peers=FITOUT_CAST_IDS.filter(peer=>peer!==id),index=Math.max(0,peers.indexOf(world.otherId)),text=story.lines.relationship[index]||castLine(id,{context:'idle'});return{text,context:'relationship',reason:resolved.reason,index,speakerId:id,otherId:world.otherId}}const pool=story.lines[resolved.context]||story.lines.idle,key=`${id}:${resolved.context}:${world.order?.phase||'site'}:${world.order?.kind||'general'}`,index=this.counts.get(key)||0;this.counts.set(key,index+1);let text=pool[index%pool.length];const last=this.lastByActor.get(id);if(text===last&&pool.length>1)text=pool[(index+1)%pool.length];this.lastByActor.set(id,text);return{text,context:resolved.context,reason:resolved.reason,index:index%pool.length,speakerId:id,orderId:world.order?.id||null}}
}
